'use strict';
/* ============================================================
   Botellas de Cami. Prototipo para CabriCoach.
   Un solo archivo, sin nada externo. El motor (MOTOR) esta arriba.
   ============================================================ */

const IMG = { celebC:'data:image/png;base64,', celebA:'data:image/png;base64,', faceC:'data:image/png;base64,', faceA:'data:image/png;base64,', rachaC:'data:image/png;base64,', rachaA:'data:image/png;base64,' };
const NOMBRES = { cami:'Cami', andres:'Andrés' };
const COLORES = ['rojo','naranja','amarillo','lima','esmeralda','cian','azul','violeta','rosa','café','perla','vino'];
const DIAS = ['dom','lun','mar','mié','jue','vie','sáb'];
const MESES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
const KEY = 'botellas:v1', KNIV = 'botellas:niveles:v1';
const $ = (id) => document.getElementById(id);

/* ---------- estado persistente ---------- */
function perfilNuevo(){ return { nivel:1, estrellas:{}, dias:{}, racha:{ actual:0, mejor:0, ultimo:null }, stats:{ ganados:0, segundos:0 } }; }
function estadoNuevo(){ return { jugador:'cami', perfiles:{ cami:perfilNuevo(), andres:perfilNuevo() }, ajustes:{ sonido:true, vibra:true, simbolos:false }, partida:null }; }
let S = estadoNuevo();
let NIV = {};
function normalizar(x){
  // tolera datos viejos o incompletos: nunca rompe, solo completa lo que falte
  const b = estadoNuevo();
  if(!x || typeof x !== 'object') return b;
  b.jugador = x.jugador === 'andres' ? 'andres' : 'cami';
  ['cami','andres'].forEach(k => { const p = (x.perfiles||{})[k]; if(p) b.perfiles[k] = Object.assign(perfilNuevo(), p, { racha:Object.assign({actual:0,mejor:0,ultimo:null}, p.racha), stats:Object.assign({ganados:0,segundos:0}, p.stats), estrellas:p.estrellas||{}, dias:p.dias||{} }); });
  b.ajustes = Object.assign(b.ajustes, x.ajustes);
  b.partida = x.partida && x.partida.estado ? x.partida : null;
  return b;
}
function guardar(){ try{ localStorage.setItem(KEY, JSON.stringify(S)); }catch(e){} }
function guardarNiveles(){
  try{
    const ks = Object.keys(NIV);
    // el cache no crece sin fin: se conservan los 90 mas recientes
    if(ks.length > 90) ks.slice(0, ks.length - 90).forEach(k => { delete NIV[k]; });
    localStorage.setItem(KNIV, JSON.stringify(NIV));
  }catch(e){}
}
function cargarTodo(data){
  let x = data && data.S;
  if(!x){ try{ x = JSON.parse(localStorage.getItem(KEY) || 'null'); }catch(e){ x = null; } }
  S = normalizar(x);
  try{ NIV = JSON.parse(localStorage.getItem(KNIV) || '{}') || {}; }catch(e){ NIV = {}; }
}
const P = () => S.perfiles[S.jugador];

/* ---------- fechas locales ---------- */
const z2 = (n) => (n < 10 ? '0' : '') + n;
function isoDe(d){ return d.getFullYear() + '-' + z2(d.getMonth()+1) + '-' + z2(d.getDate()); }
function hoyISO(){ return isoDe(new Date()); }
function ayerDe(f){ const p = f.split('-').map(Number); return isoDe(new Date(p[0], p[1]-1, p[2]-1)); }
function etiquetaFecha(f){ const p = f.split('-').map(Number); const d = new Date(p[0], p[1]-1, p[2]); return DIAS[d.getDay()] + ' ' + p[2] + ' ' + MESES[p[1]-1]; }

/* ---------- worker ---------- */
// Misma funcion en el hilo principal y en el Worker (se pasa su texto al blob)
function ejecutarOp(op, a){
  const M = MOTOR;
  if(op === 'generar') return M.generar(a.p, a.seed);
  if(op === 'pista') return M.pista(a.s, a.cap);
  if(op === 'vigilar'){
    const r = M.resolver(a.s, a.cap, { rapido:true, tope:20000 });
    return r && r.sinSolucion ? { sinSalida:true } : { ok:true };
  }
  if(op === 'retroceder'){
    // lista: estados del mas reciente al mas antiguo. Devuelve el primero que el solver resuelve.
    const t0 = Date.now();
    for(let k = 0; k < a.lista.length; k++){
      const r = M.resolver(a.lista[k], a.cap, { rapido:true, tope:20000 });
      if(r && r.movs) return { k:k };
      if(Date.now() - t0 > 3500) return { k:a.lista.length - 1 };
    }
    return { k:-1 };
  }
  throw new Error('op desconocida');
}
let W = null, wId = 0; const pend = {};
function iniciarWorker(){
  try{
    const src = $('motor').textContent + '\nvar ejecutarOp=' + ejecutarOp.toString() + ';\n' +
      'self.onmessage=function(e){var d=e.data;try{self.postMessage({id:d.id,r:ejecutarOp(d.op,d.a)})}catch(x){self.postMessage({id:d.id,err:String(x)})}};';
    const url = URL.createObjectURL(new Blob([src], { type:'text/javascript' }));
    W = new Worker(url);
    W.onmessage = (e) => { const p = pend[e.data.id]; if(!p) return; delete pend[e.data.id]; e.data.err ? p.rej(new Error(e.data.err)) : p.res(e.data.r); };
    W.onerror = () => {
      // si el Worker falla, lo que quedo pendiente se hace en el hilo principal
      W = null;
      Object.keys(pend).forEach(id => { const p = pend[id]; delete pend[id]; setTimeout(() => { try{ p.res(ejecutarOp(p.op, p.a)); }catch(x){ p.rej(x); } }, 0); });
    };
  }catch(e){ W = null; }
}
function llamar(op, a){
  return new Promise((res, rej) => {
    if(W){ const id = ++wId; pend[id] = { res, rej, op, a }; try{ W.postMessage({ id, op, a }); return; }catch(e){ delete pend[id]; W = null; } }
    setTimeout(() => { try{ res(ejecutarOp(op, a)); }catch(x){ rej(x); } }, 0);
  });
}

/* ---------- niveles ---------- */
function paramsDe(modo, clave){ return modo === 'dia' ? MOTOR.diaParams(clave) : MOTOR.nivelParams(parseInt(clave, 10)); }
function obtenerNivel(modo, clave){
  const k = (modo === 'dia' ? 'dia:' : 'camino:') + clave;
  if(NIV[k]) return Promise.resolve(NIV[k]);
  return llamar('generar', { p:paramsDe(modo, clave), seed:k }).then(n => {
    NIV[k] = { botellas:n.botellas, cap:n.cap, meta:n.meta, tipo:n.tipo, misterio:n.misterio, ocultas:n.ocultas || null, movs:n.movs };
    guardarNiveles();
    return NIV[k];
  });
}
function tipoTexto(p){
  if(p.tipo === 'dificil') return 'Difícil';
  if(p.misterio) return 'Misterio';
  if(p.tipo === 'largas') return 'Botellas largas';
  if(p.tipo === 'respiro') return 'Respiro';
  return '';
}

/* ---------- iconos y botellas (HTML) ---------- */
function htmlBloques(b, oc, split, revK, simb){
  // agrupa capas contiguas del mismo color en un solo bloque: se ven como un liquido continuo
  const bl = [], L = b.length;
  for(let k = 0; k < L; k++){
    const hid = oc && oc[k];
    const last = bl[bl.length - 1];
    const ini = split && k === L - split;
    if(!hid && last && !last.oc && last.c === b[k] && !ini) { last.n++; last.k1 = k; }
    else bl.push({ c:b[k], n:1, oc:!!hid, k0:k, k1:k, sp:!!split && k >= L - split });
  }
  let h = '';
  bl.forEach((x, idx) => {
    if(x.oc){ h += '<div class="ly oc" style="--n:1"><span>?</span></div>'; return; }
    const top = idx === bl.length - 1;
    const rev = revK !== undefined && revK !== null && revK >= x.k0 && revK <= x.k1;
    let sy = '';
    if(simb) for(let q = 0; q < x.n; q++) sy += '<i class="sy"><svg viewBox="0 0 24 24"><use href="#g' + x.c + '"/></svg></i>';
    h += '<div class="ly c' + x.c + (top ? ' top' : '') + (x.sp ? ' sp' : '') + (rev ? ' rev' : '') + '" style="--n:' + x.n + '">' + sy + '</div>';
  });
  return h;
}
function htmlBot(b, oc, cap, o){
  o = o || {};
  let h = '<div class="bwrap"><div class="glass"><div class="liq">' + htmlBloques(b, oc, o.split, o.rev, o.simb) + '</div><i class="shine"></i></div><i class="lip"></i>';
  if(MOTOR.completa(b, cap)) h += '<i class="tapa' + (o.tapaNueva ? ' cae' : '') + '"><b></b></i>' + (o.tapaNueva ? '<i class="brillo"></i>' : '');
  return h + '</div>';
}

/* ---------- geometria del tablero ---------- */
function calcTam(n, cap, W_, H_, o){
  const filas = n <= 6 ? 1 : 2, cols = Math.ceil(n / filas);
  const ratio = cap >= 6 ? 4.6 : 3.3;
  let w = Math.floor((W_ - (cols - 1) * o.gap) / cols);
  w = Math.min(w, o.maxW);
  const hFila = (H_ - (filas - 1) * o.rgap) / filas;
  w = Math.min(w, Math.floor(hFila / ratio));
  w = Math.max(o.minW, w);
  return { w:w, h:Math.round(w * ratio), filas:filas, cols:cols };
}
function filasDe(n){ const f = n <= 6 ? 1 : 2, c = Math.ceil(n / f); return f === 1 ? [[0, n]] : [[0, c], [c, n]]; }

function colocarTam(cont, t, gap, rgap){
  cont.style.setProperty('--bw', t.w + 'px');
  cont.style.setProperty('--bh', t.h + 'px');
  cont.style.setProperty('--bgap', gap + 'px');
  cont.style.setProperty('--rgap', rgap + 'px');
}

/* ============================================================
   JUEGO
   ============================================================ */
let G = null;          // partida activa
let TOK = 0;           // para descartar cargas viejas
let tickId = null;
const rm = () => !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);

function etiquetaAria(b, oc, cap, i){
  if(!b.length) return 'Botella ' + (i+1) + ': vacía. Le caben ' + cap;
  const vis = [], ocu = oc ? oc.filter(Boolean).length : 0;
  for(let k = b.length - 1; k >= 0; k--) if(!(oc && oc[k])) vis.push(COLORES[b[k]-1]);
  let t = 'Botella ' + (i+1) + ': ' + vis.join(', ');
  if(MOTOR.completa(b, cap)) return t + '. Completa';
  if(ocu) t += (vis.length ? ', ' : '') + ocu + (ocu === 1 ? ' capa oculta' : ' capas ocultas');
  const libre = cap - b.length;
  return t + (libre ? '. Le cabe' + (libre === 1 ? ' 1 más' : 'n ' + libre + ' más') : '. Llena');
}

function pintarSlot(i, o){
  const sl = G.slots[i]; if(!sl) return;
  const b = G.estado[i], oc = G.oc ? G.oc[i] : null;
  o = Object.assign({ simb:S.ajustes.simbolos }, o);
  sl.innerHTML = htmlBot(b, oc, G.cap, o);
  const comp = MOTOR.completa(b, G.cap);
  sl.classList.toggle('done', comp);
  sl.setAttribute('aria-label', etiquetaAria(b, oc, G.cap, i));
  sl.setAttribute('aria-disabled', comp ? 'true' : 'false');
  sl.setAttribute('aria-pressed', G.sel === i ? 'true' : 'false');
  sl.tabIndex = comp ? -1 : 0;
}

function construirTablero(){
  const bd = $('board');
  bd.innerHTML = ''; bd.classList.remove('sk');
  bd.classList.toggle('simb', !!S.ajustes.simbolos);
  bd.style.setProperty('--cap', G.cap);
  G.slots = [];
  filasDe(G.estado.length).forEach(r => {
    const row = document.createElement('div'); row.className = 'brow';
    for(let i = r[0]; i < r[1]; i++){
      const sl = document.createElement('div');
      sl.className = 'slot'; sl.dataset.i = i; sl.setAttribute('role', 'button');
      row.appendChild(sl); G.slots[i] = sl;
    }
    bd.appendChild(row);
  });
  for(let i = 0; i < G.estado.length; i++) pintarSlot(i);
  medir();
}

function medir(){
  const bd = $('board'); if(!bd || !G) return;
  const n = G.estado ? G.estado.length : (G.nEsq || 5);
  const cap = G.cap;
  const cs = getComputedStyle(bd);
  const W_ = bd.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
  // arriba se deja sitio para la botella levantada y para que la que vierte se incline sobre la fila de arriba
  const ratio = cap >= 6 ? 4.6 : 3.3;
  const gap = n > 9 ? 6 : 10, rgap = 26;
  let t = calcTam(n, cap, W_, bd.clientHeight - 24 - 16, { gap:gap, rgap:rgap, maxW:64, minW:22 });
  const padTop = Math.round(t.w * 1.15) + 8;
  t = calcTam(n, cap, W_, bd.clientHeight - padTop - 18, { gap:gap, rgap:rgap, maxW:64, minW:22 });
  colocarTam(bd, t, gap, rgap);
  bd.style.paddingTop = padTop + 'px';
  bd.style.paddingBottom = '18px';
  G.tam = t;
  tutorial();
}

function esqueleto(nBot, cap){
  const bd = $('board');
  G.estado = null; G.nEsq = nBot; G.cap = cap;
  bd.innerHTML = ''; bd.classList.add('sk');
  bd.style.setProperty('--cap', cap);
  filasDe(nBot).forEach(r => {
    const row = document.createElement('div'); row.className = 'brow';
    for(let i = r[0]; i < r[1]; i++){ const sl = document.createElement('div'); sl.className = 'slot'; sl.innerHTML = '<div class="bwrap"><div class="glass"><div class="liq"></div></div><i class="lip"></i></div>'; row.appendChild(sl); }
    bd.appendChild(row);
  });
  const pr = document.createElement('div'); pr.id = 'prep'; pr.textContent = 'Preparando el nivel'; bd.appendChild(pr);
  medir();
}

/* ---------- abrir / cerrar partida ---------- */
function copiaOc(o){ return o ? o.map(a => a.slice()) : null; }
function abrirJuego(modo, clave, o){
  o = o || {};
  const tok = ++TOK;
  const p = paramsDe(modo, clave);
  G = { modo:modo, clave:String(clave), cap:p.cap, estado:null, busy:true, ganado:false, sel:null, slots:[], hist:[], movs:0, extra:false, seg:0, nEsq:p.n + p.vacias, tokP:0, tokV:0 };
  document.body.classList.add('jugando');
  $('vInicio').hidden = true; $('vJuego').hidden = false;
  window.scrollTo(0, 0);
  pintarCabecera(p);
  $('strip').hidden = true;
  esqueleto(p.n + p.vacias, p.cap);
  pintarControles();
  obtenerNivel(modo, clave).then(nv => {
    if(tok !== TOK) return;
    armarPartida(nv, o);
  }).catch(() => { if(tok === TOK) toast('No pude preparar el nivel. Vuelve a intentarlo.'); });
}
function armarPartida(nv, o){
  const pa = S.partida;
  const g = G;
  g.nv = nv; g.meta = nv.meta; g.cap = nv.cap; g.tipo = nv.tipo; g.misterio = nv.misterio; g.sol = nv.movs;
  g.ini = nv.botellas; g.iniOc = nv.ocultas || null;
  g.estado = nv.botellas.map(b => b.slice()); g.oc = copiaOc(nv.ocultas);
  if(o.solo){
    // "Ver como quedo": se aplica la solucion en seco y se muestra el tablero resuelto
    nv.movs.forEach(m => { const r = MOTOR.verter(g.estado, m[0], m[1], g.cap); g.estado = r.estado; });
    g.oc = null; g.ganado = true; g.solo = true;
    const d = P().dias[g.clave]; g.movs = d ? d.movs : nv.meta;
  } else if(pa && pa.jugador === S.jugador && pa.modo === g.modo && pa.clave === g.clave){
    g.estado = pa.estado.map(b => b.slice()); g.oc = copiaOc(pa.ocultas);
    g.hist = (pa.historial || []).map(h => ({ e:h.e, o:h.o, m:h.m, x:h.x }));
    g.movs = pa.movs || 0; g.extra = !!pa.extraUsada; g.seg = pa.seg || 0;
  }
  g.busy = false; g.sel = null;
  pintarCabecera(paramsDe(g.modo, g.clave));
  construirTablero();
  pintarControles();
  if(!g.solo){ vigilar(); iniciarReloj(); }
  guardarPartida();
  // el siguiente nivel se va armando en segundo plano
  if(g.modo === 'camino') setTimeout(() => { obtenerNivel('camino', parseInt(g.clave, 10) + 1).catch(() => {}); }, 400);
}
function cerrarJuego(){
  TOK++; detenerReloj();
  document.body.classList.remove('jugando');
  $('vJuego').hidden = true; $('vInicio').hidden = false;
  cerrarHojaWin(true);
  G = null;
  pintarInicio();
}
function pintarCabecera(p){
  if(!G) return;
  if(G.modo === 'dia'){
    $('gNivel').textContent = 'Reto del día';
    const t = tipoTexto(p);
    setChip(t || etiquetaFecha(G.clave));
  } else {
    $('gNivel').textContent = 'Nivel ' + G.clave;
    setChip(tipoTexto(p));
  }
  $('gMeta').textContent = G.meta !== undefined ? G.meta : '·';
  $('gMovs').textContent = G.movs || 0;
}
function setChip(t){ const c = $('gChip'); c.hidden = !t; c.textContent = t || ''; c.classList.toggle('acc', !!t); }
function pintarControles(){
  const ok = G && G.estado && !G.solo;
  $('cUndo').disabled = !ok || G.busy || !G.hist.length;
  $('cReset').disabled = !ok || G.busy;
  $('cHint').disabled = !ok || G.busy || G.ganado;
  $('cExtra').disabled = !ok || G.busy || G.extra || G.ganado;
  $('extraBdg').classList.toggle('off', !ok || G.extra);
  $('gMovs').textContent = G ? (G.movs || 0) : 0;
}

/* ---------- reloj silencioso (solo para estadisticas) ---------- */
function iniciarReloj(){ detenerReloj(); tickId = setInterval(() => { if(G && G.estado && !G.ganado && !document.hidden) G.seg++; }, 1000); }
function detenerReloj(){ if(tickId){ clearInterval(tickId); tickId = null; } }

/* ---------- partida persistente ---------- */
function snap(){ return { e:G.estado, o:G.oc, m:G.movs, x:G.extra }; }
function guardarPartida(){
  if(!G || !G.estado || G.solo){ return; }
  if(G.ganado){ S.partida = null; guardar(); return; }
  S.partida = { jugador:S.jugador, modo:G.modo, clave:G.clave, estado:G.estado, ocultas:G.oc, historial:G.hist.slice(-150), movs:G.movs, extraUsada:G.extra, seg:G.seg };
  guardar();
}

/* ---------- toques ---------- */
function puedeOrigen(i){ for(let j = 0; j < G.estado.length; j++) if(MOTOR.puedeVerter(G.estado, i, j, G.cap)) return true; return false; }
function sacudir(i){ const s = G.slots[i]; if(!s) return; s.classList.remove('shake'); void s.offsetWidth; s.classList.add('shake'); setTimeout(() => s.classList.remove('shake'), 420); }
function seleccionar(i){
  if(G.sel !== null && G.slots[G.sel]){ G.slots[G.sel].classList.remove('sel'); G.slots[G.sel].setAttribute('aria-pressed', 'false'); }
  G.sel = i;
  if(i !== null){ G.slots[i].classList.add('sel'); G.slots[i].setAttribute('aria-pressed', 'true'); }
  tutorial();
}
function tocar(i){
  if(!G || !G.estado || G.busy || G.ganado || G.solo) return;
  despertarAudio();
  if(G.pistaT){ limpiarPista(); }
  const s = G.estado;
  if(G.sel === null){
    if(MOTOR.completa(s[i], G.cap) || !s[i].length) { sacudir(i); return; }
    if(puedeOrigen(i)) seleccionar(i); else { sacudir(i); sonar('malo'); }
    return;
  }
  if(G.sel === i){ seleccionar(null); return; }
  if(MOTOR.puedeVerter(s, G.sel, i, G.cap)){ verterAnim(G.sel, i); return; }
  // si lo tocado puede ser origen, se cambia la seleccion; si no, golpe sordo
  if(!MOTOR.completa(s[i], G.cap) && s[i].length && puedeOrigen(i)){ seleccionar(i); return; }
  sacudir(i); sonar('malo');
}

/* ---------- el vertido ---------- */
const esperar = (ms) => new Promise(r => setTimeout(r, ms));
function fin(a){ return new Promise(r => { a.onfinish = r; a.oncancel = r; }); }
function relRect(el, br){ const r = el.getBoundingClientRect(); return { left:r.left - br.left, top:r.top - br.top, width:r.width, height:r.height }; }

async function verterAnim(i, j){
  const g = G, cap = g.cap;
  g.busy = true; pintarControles();
  ocultarStrip(); limpiarPista(); ocultarTip();
  const sl = g.slots[i];
  seleccionar(null);
  g.hist.push(snap());
  const antes = g.estado;
  const r = MOTOR.verter(antes, i, j, cap);
  const q = r.cantidad, color = r.color;
  const n0 = antes[j].length;
  // estado nuevo (siempre arreglos nuevos: el historial guarda referencias)
  let ocS = null, ocD = null, revK = null;
  if(g.oc){
    ocS = g.oc[i].slice(0, antes[i].length - q);
    if(ocS.length && ocS[ocS.length - 1]){ ocS[ocS.length - 1] = false; revK = ocS.length - 1; }
    ocD = g.oc[j].concat(new Array(q).fill(false));
  }
  const nuevoOc = g.oc ? g.oc.map((a, k) => k === i ? ocS : (k === j ? ocD : a)) : null;
  const compAntes = MOTOR.completa(antes[j], cap);

  if(!rm()){
    const bd = $('board'), br = bd.getBoundingClientRect();
    const dl = g.slots[j];
    const Sr = relRect(sl, br), Dr = relRect(dl, br);
    const bw = g.tam.w, bh = g.tam.h;
    const wrap = sl.firstElementChild;
    // el origen se dibuja con las capas que caen separadas, para poder vaciarlas
    sl.querySelector('.liq').innerHTML = htmlBloques(antes[i], g.oc ? g.oc[i] : null, q, null, S.ajustes.simbolos);
    sl.style.zIndex = 50; dl.style.zIndex = 10;
    const Scx = Sr.left + Sr.width / 2, Dcx = Dr.left + Dr.width / 2;
    const dir = Dcx > Scx ? 1 : (Dcx < Scx ? -1 : (Dcx < br.width / 2 ? -1 : 1));
    const th = (55 + 20 * q / cap) * Math.PI / 180;
    const thGr = th * 180 / Math.PI;
    const originY = Dr.top - 0.3 * bw;
    const pivX = Dcx - dir * (bw / 2) * Math.cos(th);
    const pivY = originY - (bw / 2) * Math.sin(th);
    const tx = pivX - Scx, ty = pivY - Sr.top;
    const EA = 'cubic-bezier(.32,.72,0,1)';
    const anims = [];
    const A = (el, kf, op) => { const a = el.animate(kf, Object.assign({ fill:'forwards' }, op)); anims.push(a); return a; };
    // 1) viaja hasta quedar con la boca arriba, al lado de la boca de destino
    sonar('verter');
    await fin(A(wrap, [{ transform:'translate(0,-16px)' }, { transform:'translate(' + tx + 'px,' + ty + 'px)' }], { duration:180, easing:EA }));
    // 2) se inclina hacia el destino
    await fin(A(wrap, [{ transform:'translate(' + tx + 'px,' + ty + 'px) rotate(0deg)' }, { transform:'translate(' + tx + 'px,' + ty + 'px) rotate(' + (dir * thGr) + 'deg)' }], { duration:110, easing:'ease-in-out' }));
    // 3) chorro + las capas bajan en el origen y suben en el destino
    const sw = Math.max(4, Math.round(bw * 0.14));
    const surf = (n) => Dr.top + 1.5 + (bh - 3) * (1 - n / cap);
    const y0 = surf(n0), y1 = surf(n0 + q);
    const st = document.createElement('i');
    st.className = 'chorro c' + color;
    st.style.left = (Dcx - sw / 2) + 'px'; st.style.top = originY + 'px'; st.style.width = sw + 'px';
    st.style.height = Math.max(6, y1 - originY) + 'px';
    bd.appendChild(st);
    const DUR = 260, EQ = 'cubic-bezier(.4,0,.6,1)';
    const lista = [];
    lista.push(fin(A(st, [{ transform:'scaleY(0)' }, { transform:'scaleY(1)' }], { duration:80, easing:'ease-out' })));
    lista.push(fin(A(st, [{ height:Math.max(6, y0 - originY) + 'px' }, { height:Math.max(6, y1 - originY) + 'px' }], { duration:DUR, easing:EQ })));
    const pour = sl.querySelector('.ly.sp');
    if(pour) lista.push(fin(A(pour, [{ height:(q / cap * 100) + '%' }, { height:'0%' }], { duration:DUR, easing:EQ })));
    const dliq = dl.querySelector('.liq');
    const nb = document.createElement('div'); nb.className = 'ly c' + color; nb.style.setProperty('--n', q); nb.style.height = '0%';
    dliq.appendChild(nb);
    lista.push(fin(A(nb, [{ height:'0%' }, { height:(q / cap * 100) + '%' }], { duration:DUR, easing:EQ })));
    lista.push(fin(A(wrap, [{ transform:'translate(' + tx + 'px,' + ty + 'px) rotate(' + (dir * thGr) + 'deg)' }, { transform:'translate(' + tx + 'px,' + ty + 'px) rotate(' + (dir * (thGr + 7)) + 'deg)' }], { duration:DUR, easing:'linear' })));
    await Promise.all(lista);
    // 4) el chorro se retira y la botella vuelve a su lugar
    const ret = fin(A(st, [{ transform:'scaleY(1)', transformOrigin:'50% 100%' }, { transform:'scaleY(0)', transformOrigin:'50% 100%' }], { duration:80, easing:'ease-in' }));
    const vuelta = fin(A(wrap, [{ transform:'translate(' + tx + 'px,' + ty + 'px) rotate(' + (dir * (thGr + 7)) + 'deg)' }, { transform:'translate(0,0) rotate(0deg)' }], { duration:190, easing:EA }));
    await Promise.all([ret, vuelta]);
    st.remove();
    // se pinta el estado limpio antes de soltar las animaciones, para que no haya salto
    aplicarEstado(i, j, r.estado, nuevoOc, revK, compAntes);
    anims.forEach(a => { try{ a.cancel(); }catch(e){} });
    sl.style.zIndex = ''; dl.style.zIndex = '';
  } else {
    aplicarEstado(i, j, r.estado, nuevoOc, revK, compAntes);
    [i, j].forEach(k => { const lq = g.slots[k].querySelector('.liq'); if(lq){ lq.classList.add('fadein'); } });
    sonar('verter');
  }
  tras(i, j, q, color);
}
function aplicarEstado(i, j, estado, oc, revK, compAntes){
  const g = G;
  g.estado = estado; g.oc = oc; g.movs++;
  const nuevaTapa = !compAntes && MOTOR.completa(estado[j], g.cap);
  pintarSlot(i, { rev:revK });
  pintarSlot(j, { tapaNueva:nuevaTapa });
  g.tapaNueva = nuevaTapa;
}
function tras(i, j, q, color){
  const g = G; if(!g) return;
  g.busy = false;
  vib(8);
  anunciar('Vertiste ' + COLORES[color - 1] + ' en la botella ' + (j + 1));
  $('gMovs').textContent = g.movs;
  if(g.tapaNueva){
    sonar('tapa'); vib(18);
    anunciar('Botella ' + (j + 1) + ' completa');
  }
  pintarControles();
  guardarPartida();
  if(MOTOR.ganado(g.estado, g.cap)){
    g.ganado = true; guardarPartida(); pintarControles();
    setTimeout(() => { if(G === g) ganar(); }, 350);
    return;
  }
  vigilar();
  tutorial();
}

/* ---------- sin salida ---------- */
function vigilar(){
  const g = G; if(!g || !g.estado) return;
  const tok = ++g.tokV;
  if(!MOTOR.hayJugadas(g.estado, g.cap)){ mostrarStrip(); return; }
  llamar('vigilar', { s:g.estado, cap:g.cap }).then(r => {
    if(G === g && tok === g.tokV && r && r.sinSalida) mostrarStrip();
  }).catch(() => {});
}
function ocultarStrip(){ if(G) G.tokV++; $('strip').hidden = true; if(G && G.estado) setTimeout(medir, 0); }
function mostrarStrip(){
  const g = G; const st = $('strip');
  st.innerHTML = '<div class="t-body">Por aquí ya no hay salida.</div><div class="acts"></div>';
  const ac = st.querySelector('.acts');
  const b1 = document.createElement('button'); b1.type = 'button'; b1.className = 'btn t-btn'; b1.textContent = 'Volver al último punto con salida';
  b1.onclick = volverConSalida; ac.appendChild(b1);
  if(!g.extra){
    const b2 = document.createElement('button'); b2.type = 'button'; b2.className = 'btn t-btn'; b2.textContent = 'Usar la botella extra';
    b2.onclick = botellaExtra; ac.appendChild(b2);
  }
  st.hidden = false;
  anunciar('Por aquí ya no hay salida.');
  setTimeout(medir, 0);
}
function restaurar(h){
  const g = G;
  g.estado = h.e; g.oc = h.o; g.movs = h.m; g.extra = h.x; g.sel = null; g.ganado = false;
  construirTablero(); pintarControles(); guardarPartida();
}
function volverConSalida(){
  const g = G; if(!g || g.busy) return;
  g.busy = true;
  const lista = g.hist.slice().reverse().map(h => h.e);
  const fallback = () => { g.busy = false; };
  if(!lista.length){ g.busy = false; reiniciar(); return; }
  llamar('retroceder', { lista:lista, cap:g.cap }).then(r => {
    if(G !== g) return;
    g.busy = false;
    ocultarStrip();
    if(r.k < 0){ const h0 = g.hist[0]; g.hist = []; restaurar(h0); toast('Empezamos de nuevo desde el principio'); return; }
    const idx = g.hist.length - 1 - r.k;
    const h = g.hist[idx];
    g.hist = g.hist.slice(0, idx);
    restaurar(h);
    toast('Volviste a un punto con salida');
  }).catch(fallback);
}

/* ---------- controles ---------- */
function deshacer(){
  const g = G; if(!g || g.busy || !g.hist.length || g.solo) return;
  g.ganado = false;
  ocultarStrip(); limpiarPista(); ocultarTip();
  const h = g.hist.pop();
  restaurar(h); vigilar();
}
function reiniciar(){
  const g = G; if(!g || g.busy || g.solo) return;
  // se guarda como una jugada mas: Deshacer devuelve la partida y no hace falta preguntar
  g.hist.push(snap());
  g.estado = g.ini.map(b => b.slice()); g.oc = copiaOc(g.iniOc); g.movs = 0; g.extra = false; g.sel = null; g.ganado = false;
  ocultarStrip(); limpiarPista();
  construirTablero(); pintarControles(); guardarPartida(); vigilar(); tutorial();
  toast('Empezaste de nuevo. Deshacer te devuelve la partida.');
}
function botellaExtra(){
  const g = G; if(!g || g.busy || g.extra || g.ganado || g.solo) return;
  g.hist.push(snap());
  g.estado = g.estado.concat([[]]); if(g.oc) g.oc = g.oc.concat([[]]);
  g.extra = true; g.sel = null;
  ocultarStrip(); limpiarPista();
  construirTablero(); pintarControles(); guardarPartida(); vigilar();
  anunciar('Agregaste una botella vacía');
}
function limpiarPista(){
  if(!G) return;
  if(G.pistaT){ clearTimeout(G.pistaT); G.pistaT = null; }
  (G.slots || []).forEach(s => s && s.classList.remove('hint-o', 'hint-d'));
}
function pedirPista(){
  const g = G; if(!g || g.busy || g.ganado || g.solo) return;
  limpiarPista(); ocultarTip();
  if(g.sel !== null) seleccionar(null);
  const tok = ++g.tokP;
  llamar('pista', { s:g.estado, cap:g.cap }).then(r => {
    if(G !== g || tok !== g.tokP) return;
    if(r.sinSalida){ mostrarStrip(); return; }
    if(r.desconocido || !r.mov){ toast('Esta está enredada: prueba deshacer un par de movimientos'); return; }
    g.slots[r.mov[0]].classList.add('hint-o');
    g.slots[r.mov[1]].classList.add('hint-d');
    g.pistaT = setTimeout(limpiarPista, 2500);
  }).catch(() => {});
}

/* ---------- tutorial (niveles 1 y 2) ---------- */
function ocultarTip(){ const t = document.getElementById('tip'); if(t) t.remove(); }
function tutorial(){
  ocultarTip();
  const g = G;
  if(!g || !g.estado || g.busy || g.ganado || g.solo || g.modo !== 'camino' || parseInt(g.clave, 10) > 2 || g.movs > 0 || g.hist.length || !g.sol || !g.sol.length) return;
  const m = g.sol[0];
  let idx, txt;
  if(g.sel === null){ idx = m[0]; txt = 'Toca esta botella'; }
  else if(g.sel === m[0]){ idx = m[1]; txt = 'Ahora esta'; }
  else return;
  const sl = g.slots[idx]; if(!sl) return;
  const bd = $('board'), br = bd.getBoundingClientRect(), r = sl.getBoundingClientRect();
  const tip = document.createElement('div'); tip.id = 'tip'; tip.className = 'tip'; tip.textContent = txt;
  bd.appendChild(tip);
  const w = tip.offsetWidth, h = tip.offsetHeight;
  const cx = r.left - br.left + r.width / 2;
  let left = Math.max(10, Math.min(br.width - w - 10, cx - w / 2));
  tip.style.left = left + 'px';
  tip.style.top = Math.max(4, r.top - br.top - h - 30) + 'px';
  tip.style.setProperty('--ax', (cx - left) + 'px');
}

/* ---------- ganar ---------- */
function estrellaSvg(on){ return '<svg viewBox="0 0 24 24" class="' + (on ? 'on' : 'off') + '"' + (on ? ' style="animation-delay:' + 0 + 'ms"' : '') + '><path d="M12 3.2l2.6 5.5 6 .8-4.4 4.2 1.1 6-5.3-2.9-5.3 2.9 1.1-6L3.4 9.5l6-.8z"/></svg>'; }
function tiempoTxt(s){ return Math.floor(s / 60) + ':' + z2(s % 60); }
function ganar(){
  const g = G; if(!g) return;
  detenerReloj();
  const est = MOTOR.estrellasDe(g.movs, g.meta);
  const pf = P();
  pf.stats.ganados++; pf.stats.segundos += g.seg;
  if(g.modo === 'camino'){
    const L = parseInt(g.clave, 10);
    if(!pf.estrellas[L] || est > pf.estrellas[L]) pf.estrellas[L] = est;
    if(L === pf.nivel) pf.nivel = L + 1;
  } else {
    const prev = pf.dias[g.clave];
    if(!prev || est > prev.estrellas || (est === prev.estrellas && g.movs < prev.movs)) pf.dias[g.clave] = { movs:g.movs, estrellas:est, seg:g.seg };
    if(pf.racha.ultimo !== g.clave){
      pf.racha.actual = pf.racha.ultimo === ayerDe(g.clave) ? pf.racha.actual + 1 : 1;
      pf.racha.mejor = Math.max(pf.racha.mejor, pf.racha.actual);
      pf.racha.ultimo = g.clave;
    }
  }
  S.partida = null; guardar();
  const dia = g.modo === 'dia';
  $('wImg').src = S.jugador === 'cami' ? IMG.celebC : IMG.celebA;
  $('wLabel').textContent = dia ? 'Reto del día' : 'Nivel ' + g.clave;
  $('wTit').textContent = dia ? 'Reto del día resuelto' : 'Nivel superado';
  $('wMovs').textContent = g.movs; $('wMeta').textContent = g.meta; $('wTiempo').textContent = tiempoTxt(g.seg);
  let h = '';
  for(let k = 0; k < 3; k++) h += estrellaSvg(k < est).replace('animation-delay:0ms', 'animation-delay:' + (300 + k * 120) + 'ms');
  $('wEst').innerHTML = h;
  $('wEst').setAttribute('aria-label', est + (est === 1 ? ' estrella' : ' estrellas'));
  $('wSig').textContent = dia ? 'Volver al inicio' : 'Siguiente nivel';
  confettiBurst();
  sonar('ganar'); vib([30, 40, 60]);
  $('veloWin').classList.add('on');
  setTimeout(() => $('wSig').focus({ preventScroll:true }), 300);
  anunciar((dia ? 'Reto del día resuelto' : 'Nivel superado') + '. ' + est + (est === 1 ? ' estrella' : ' estrellas'));
}
function cerrarHojaWin(rapido){ $('veloWin').classList.remove('on'); }
function siguiente(){
  const g = G; if(!g) return;
  cerrarHojaWin();
  if(g.modo === 'dia'){ cerrarJuego(); return; }
  abrirJuego('camino', parseInt(g.clave, 10) + 1);
}
function repetir(){
  const g = G; if(!g) return;
  cerrarHojaWin();
  const modo = g.modo, clave = g.clave;
  S.partida = null;
  abrirJuego(modo, clave);
}

/* ============================================================
   INICIO
   ============================================================ */
function pintarInicio(){
  const u = S.jugador, pf = P();
  document.documentElement.setAttribute('data-user', u);
  $('whoImg').src = u === 'cami' ? IMG.faceC : IMG.faceA;
  $('whoNom').textContent = NOMBRES[u];
  $('who').setAttribute('aria-label', 'Jugador: ' + NOMBRES[u] + '. Toca para cambiar');
  const L = pf.nivel, p = MOTOR.nivelParams(L), t = tipoTexto(p);
  $('hNivel').textContent = 'Nivel ' + L;
  $('hSub').textContent = p.n + ' colores · ' + (p.n + p.vacias) + ' botellas' + (t ? ' · ' + t : '');
  const pa = S.partida;
  const sigue = pa && pa.jugador === u && pa.modo === 'camino' && pa.clave === String(L) && pa.movs > 0;
  $('hJugar').textContent = (sigue ? 'Seguir el nivel ' : 'Jugar el nivel ') + L;
  // vista previa del tablero real del nivel
  const pv = $('prevHero'); pv.innerHTML = '';
  const tokPv = ++pvTok;
  pintarPreview(pv, { botellas:Array.from({ length:p.n + p.vacias }, () => []), cap:p.cap, ocultas:null }, true);
  obtenerNivel('camino', L).then(nv => { if(tokPv === pvTok) pintarPreview(pv, nv, false); }).catch(() => {});

  const hoy = hoyISO();
  $('rLabel').textContent = 'Reto del día · ' + etiquetaFecha(hoy);
  const d = pf.dias[hoy];
  $('rEstado').textContent = d ? 'Resuelto en ' + d.movs + ' movimientos · ' + d.estrellas + (d.estrellas === 1 ? ' estrella' : ' estrellas') : 'Todavía sin jugar';
  $('rJugar').textContent = d ? 'Ver cómo quedó' : 'Jugar el reto';
  $('rImg').src = u === 'cami' ? IMG.rachaC : IMG.rachaA;
  const vigente = pf.racha.ultimo === hoy || pf.racha.ultimo === ayerDe(hoy);
  const n = vigente ? pf.racha.actual : 0;
  $('rRacha').innerHTML = n ? n + '<small>' + (n === 1 ? 'día seguido' : 'días seguidos') + '</small>' : '<small style="margin:0">Hoy puedes empezar tu racha</small>';
  const sumaEst = Object.keys(pf.estrellas).reduce((a, k) => a + pf.estrellas[k], 0);
  $('sNiv').textContent = pf.nivel - 1; $('sEst').textContent = sumaEst; $('sRac').textContent = pf.racha.mejor;
  document.querySelectorAll('.sw').forEach(b => b.setAttribute('aria-checked', S.ajustes[b.dataset.aj] ? 'true' : 'false'));
}
let pvTok = 0;
function pintarPreview(cont, nv, esq){
  const n = nv.botellas.length, cap = nv.cap;
  const W_ = Math.min(cont.parentElement.clientWidth || 300, 520) - 4;
  const gap = n > 9 ? 4 : 6, rgap = 10;
  const t = calcTam(n, cap, W_, 178, { gap:gap, rgap:rgap, maxW:40, minW:12 });
  cont.innerHTML = '';
  cont.className = esq ? 'sk' : '';
  cont.style.setProperty('--cap', cap);
  colocarTam(cont, t, gap, rgap);
  const wrap = document.createElement('div');
  filasDe(n).forEach(r => {
    const row = document.createElement('div'); row.className = 'brow';
    for(let i = r[0]; i < r[1]; i++){
      const sl = document.createElement('div'); sl.className = 'slot';
      sl.innerHTML = htmlBot(nv.botellas[i], nv.ocultas ? nv.ocultas[i] : null, cap, { simb:false });
      row.appendChild(sl);
    }
    wrap.appendChild(row);
  });
  cont.appendChild(wrap);
}

/* hoja de confirmacion dentro de la pagina (nada de confirm() nativo) */
function hojaConfirmar(o){
  return new Promise(res => {
    $('cTit').textContent = o.titulo; $('cTxt').textContent = o.texto;
    $('cSi').textContent = o.ok; $('cNo').textContent = o.cancel;
    const v = $('veloConf');
    const previo = document.activeElement;
    const cierra = (val) => { v.classList.remove('on'); document.removeEventListener('keydown', kd); v.onclick = null; $('cSi').onclick = $('cNo').onclick = null; if(previo && previo.focus) previo.focus({ preventScroll:true }); res(val); };
    const kd = (e) => { if(e.key === 'Escape') cierra(false); };
    document.addEventListener('keydown', kd);
    $('cSi').onclick = () => cierra(true); $('cNo').onclick = () => cierra(false);
    v.onclick = (e) => { if(e.target === v) cierra(false); };
    v.classList.add('on');
    setTimeout(() => $('cNo').focus({ preventScroll:true }), 60);
  });
}

/* ---------- utilidades de interfaz ---------- */
let toastT = null;
function toast(t){ const e = $('toast'); e.textContent = t; e.classList.add('show'); clearTimeout(toastT); toastT = setTimeout(() => e.classList.remove('show'), 2600); }
function anunciar(t){ const l = $('live'); l.textContent = ''; setTimeout(() => { l.textContent = t; }, 30); }

function confettiBurst(){
  try{
    if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const cv = document.createElement('canvas'); cv.className = 'cfetti';
    cv.width = innerWidth; cv.height = innerHeight;
    document.body.appendChild(cv);
    const x = cv.getContext('2d'), cols = ['#FFD700','#FF5A7A','#58DFA3','#5AA9FF','#FFC94D','#C77DFF'];
    const N = Math.min(140, Math.round(innerWidth / 3)), Pp = [];
    for(let i = 0; i < N; i++) Pp.push({ x:innerWidth * (0.15 + 0.7 * (i / N)), y:-20 - Math.round(60 * (i % 7) / 7), vx:(((i * 53) % 100) / 100 - 0.5) * 5, vy:2 + ((i * 29) % 100) / 28, r:4 + ((i * 17) % 6), c:cols[i % cols.length], a:((i * 37) % 360), va:(((i * 7) % 10) - 5) * 0.9 });
    let t0 = null;
    const step = (ts) => { if(t0 === null) t0 = ts; const el = ts - t0;
      x.clearRect(0, 0, cv.width, cv.height);
      Pp.forEach(p => { p.vy += 0.12; p.x += p.vx; p.y += p.vy; p.a += p.va;
        x.save(); x.translate(p.x, p.y); x.rotate(p.a * Math.PI / 180);
        x.globalAlpha = Math.max(0, 1 - el / 1900); x.fillStyle = p.c; x.fillRect(-p.r / 2, -p.r / 2, p.r, p.r * 1.5); x.restore(); });
      if(el < 1900) requestAnimationFrame(step); else cv.remove();
    };
    requestAnimationFrame(step);
  }catch(e){}
}

/* ---------- sonido (Web Audio sintetizado, sin archivos) y vibracion ---------- */
let AC = null;
function despertarAudio(){
  try{
    if(!AC){ const C = window.AudioContext || window.webkitAudioContext; if(C) AC = new C(); }
    if(AC && AC.state === 'suspended') AC.resume();
  }catch(e){ AC = null; }
  return AC;
}
function nota(f0, f1, t0, dur, tipo, vol){
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = tipo; o.frequency.setValueAtTime(f0, t0);
  if(f1 !== f0) o.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
  g.gain.setValueAtTime(0.0001, t0);
  g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
  g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  o.connect(g); g.connect(AC.destination);
  o.start(t0); o.stop(t0 + dur + 0.03);
}
function sonar(tipo){
  if(!S.ajustes.sonido) return;
  try{
    if(!despertarAudio()) return;
    const t = AC.currentTime;
    if(tipo === 'verter'){
      // agua: ruido pasa-banda que baja de 900 a 500 Hz, mas un "glu" senoidal corto
      const n = Math.floor(AC.sampleRate * 0.3), buf = AC.createBuffer(1, n, AC.sampleRate), d = buf.getChannelData(0);
      for(let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
      const src = AC.createBufferSource(); src.buffer = buf;
      const bp = AC.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 4;
      bp.frequency.setValueAtTime(900, t); bp.frequency.exponentialRampToValueAtTime(500, t + 0.3);
      const g = AC.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(0.1, t + 0.04); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.3);
      src.connect(bp); bp.connect(g); g.connect(AC.destination); src.start(t);
      nota(420, 260, t + 0.06, 0.12, 'sine', 0.07);
    } else if(tipo === 'tapa'){
      nota(880, 880, t, 0.09, 'sine', 0.1); nota(1320, 1320, t + 0.09, 0.09, 'sine', 0.09);
    } else if(tipo === 'malo'){
      nota(140, 140, t, 0.09, 'triangle', 0.12);
    } else if(tipo === 'ganar'){
      [523, 659, 784, 1047].forEach((f, k) => nota(f, f, t + k * 0.11, 0.11, 'sine', 0.1));
    }
  }catch(e){}
}
function vib(p){ if(S.ajustes.vibra && navigator.vibrate){ try{ navigator.vibrate(p); }catch(e){} } }

/* ============================================================
   EVENTOS Y ARRANQUE
   ============================================================ */
function engancharEventos(){
  $('board').addEventListener('click', (e) => { const s = e.target.closest('.slot'); if(s && s.dataset.i !== undefined) tocar(parseInt(s.dataset.i, 10)); });
  $('board').addEventListener('keydown', (e) => {
    if(e.key !== 'Enter' && e.key !== ' ') return;
    const s = e.target.closest('.slot'); if(!s || s.dataset.i === undefined) return;
    e.preventDefault(); tocar(parseInt(s.dataset.i, 10));
  });
  $('gBack').onclick = cerrarJuego;
  $('cUndo').onclick = deshacer; $('cReset').onclick = reiniciar; $('cHint').onclick = pedirPista; $('cExtra').onclick = botellaExtra;
  $('wSig').onclick = siguiente; $('wRep').onclick = repetir;
  $('hJugar').onclick = () => { despertarAudio(); abrirJuego('camino', P().nivel); };
  $('rJugar').onclick = () => { despertarAudio(); const f = hoyISO(); abrirJuego('dia', f, { solo:!!P().dias[f] }); };
  $('who').onclick = () => { S.jugador = S.jugador === 'cami' ? 'andres' : 'cami'; guardar(); pintarInicio(); };
  document.querySelectorAll('.schedhead').forEach(h => h.addEventListener('click', () => {
    const c = h.parentElement; const ab = !c.classList.contains('open');
    c.classList.toggle('open', ab); h.setAttribute('aria-expanded', ab ? 'true' : 'false');
  }));
  document.querySelectorAll('.sw').forEach(b => b.addEventListener('click', () => {
    const k = b.dataset.aj; S.ajustes[k] = !S.ajustes[k]; guardar();
    b.setAttribute('aria-checked', S.ajustes[k] ? 'true' : 'false');
    if(k === 'sonido' && S.ajustes.sonido){ despertarAudio(); sonar('tapa'); }
    if(k === 'vibra' && S.ajustes.vibra) vib(12);
  }));
  $('borrar').onclick = async () => {
    const ok = await hojaConfirmar({ titulo:'¿Borrar el progreso de ' + NOMBRES[S.jugador] + '?', texto:'Vuelves al nivel 1 y se pierde la racha.', ok:'Borrar progreso', cancel:'Conservar' });
    if(!ok) return;
    S.perfiles[S.jugador] = perfilNuevo();
    if(S.partida && S.partida.jugador === S.jugador) S.partida = null;
    guardar(); pintarInicio(); toast('Progreso borrado');
  };
  window.addEventListener('resize', () => { if(G && !$('vJuego').hidden) medir(); else pintarInicio(); });
  document.addEventListener('pointerdown', despertarAudio, { once:true });
  // estas dos lineas evitan el zoom por doble toque en iPhone
  document.addEventListener('gesturestart', (e) => e.preventDefault());
  if(window.ResizeObserver){ new ResizeObserver(() => { if(G && G.estado && !$('vJuego').hidden) medir(); }).observe($('board')); }
}

function start(data){
  cargarTodo(data || {});
  iniciarWorker();
  engancharEventos();
  document.documentElement.setAttribute('data-user', S.jugador);
  pintarInicio();
  const m = (location.hash || '').match(/^#(?:nivel(\d{1,3})|(dia))$/);
  if(m){ if(m[1]) abrirJuego('camino', parseInt(m[1], 10)); else abrirJuego('dia', hoyISO()); }
  if(window.claude && window.claude.hot && window.claude.hot.snapshot) window.claude.hot.snapshot(() => ({ S:S }));
}

const boot = (data) => start(data);
window.claude?.hot?.ready ? window.claude.hot.ready(boot) : boot(window.claude?.hot?.data ?? {});
window.claude?.hot?.snapshot?.(() => ({ S:S }));


window.__botellas = {
  get G(){ return G; },
  S: () => S,
  motor: MOTOR,
  abrir: (m, c, o) => abrirJuego(m, c, o),
  tocar: (i) => tocar(i),
  libre: async () => { for(let k = 0; k < 400; k++){ if(G && G.estado && !G.busy) return true; await esperar(25); } return false; },
  // juega la solucion del motor; dejar = cuantos movimientos se dejan sin jugar
  resolver: async (dejar) => {
    await window.__botellas.libre();
    const sol = MOTOR.resolver(G.estado, G.cap).movs;
    for(let k = 0; k < sol.length - (dejar || 0); k++){
      tocar(sol[k][0]); await esperar(120);
      tocar(sol[k][1]); await esperar(80);
      await window.__botellas.libre();
    }
    return sol.length;
  },
  forzar: (e) => { G.estado = e; G.oc = null; G.sel = null; construirTablero(); pintarControles(); vigilar(); },
  volver: () => volverConSalida(),
  pausar: (t) => { document.getAnimations().forEach(a => { try{ a.pause(); if(t !== undefined) a.currentTime = t; }catch(e){} }); },
  reanudar: () => { document.getAnimations().forEach(a => { try{ a.play(); }catch(e){} }); }
};

